/**
 * The event of the wire items of one event, `[type name, field, ...]`, as the
 * bridge gives them: every integer is a `bigint`. A refusal quotes a name from
 * the wire cut to 64 characters.
 */
export function decodeEvent(
  items: ReadonlyArray<WireJson>,
): DecodeResult<AnyEvent, EventDecodeError> {
  const [tag, ...fields] = items;

  if (typeof tag !== "string") {
    return { ok: false, error: NOT_AN_EVENT };
  }

  switch (tag) {
    case "TaskClaimed":
      return eventResult("TaskClaimed", readTaskClaimed(fields));
    case "ClaimReleased":
      return eventResult("ClaimReleased", readClaimReleased(fields));
    case "AttemptPlaced":
      return eventResult("AttemptPlaced", readAttemptPlaced(fields));
    case "AttemptNotStarted":
      return eventResult("AttemptNotStarted", readAttemptNotStarted(fields));
    case "AttemptEnded":
      return eventResult("AttemptEnded", readAttemptEnded(fields));
    case "AttemptRecorded":
      return eventResult("AttemptRecorded", readAttemptRecorded(fields));
    case "TaskRecovered":
      return eventResult("TaskRecovered", readTaskRecovered(fields));
    case "ChildStarted":
      return eventResult("ChildStarted", readChildStarted(fields));
    case "ChildReplaced":
      return eventResult("ChildReplaced", readChildReplaced(fields));
    case "SlotDown":
      return eventResult("SlotDown", readSlotDown(fields));
    case "SlotRecovered":
      return eventResult("SlotRecovered", readSlotRecovered(fields));
    default:
      return { ok: false, error: Object.freeze({ kind: "unknownEventType", tag: cutName(tag) }) };
  }
}
